-- GENERATED by scripts/db_export_schema.py from the live database. Do not hand-edit.
CREATE OR REPLACE FUNCTION digest.member_billing(p_phone text)
 RETURNS TABLE(membership_status text, plan_name text, plan_price text, subscription_status text, billing_interval text, monthly_amount text, annual_payment text, member_since text, year_joined text, next_renewal text, chapter text, next_invoice_date text, next_invoice_amount text, payment_frequency text, membership_fee text, mds_credit text, credit_source text, billing_portal text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'digest', 'public', 'extensions'
AS $function$
declare v_n int; v_atid text;
begin
  select case when digest.resolve_asker(p_phone) is not null then 1 else 0 end into v_n;
  if v_n <> 1 then return; end if;
  select digest.resolve_asker(p_phone) into v_atid;
  if v_atid is null then return; end if;
  return query
  select
         case ma.membership_status
           when 'Current Member' then 'Active member'
           when 'New Member' then 'Active member (recently joined)'
           when 'Pending Group Entrance' then 'Active member (onboarding)'
           when 'Current Member- Not Renewing' then 'Active through the end of your term (set not to renew)'
           when 'Staff' then 'MDS team'
           else 'Active member'
         end,
         digest.attr_clean(mp.at_fields->>'Stripe Product Name'),
         coalesce(digest.attr_clean(mp.at_fields->>'Stripe Price Name'),
                  case when coalesce(mp.at_fields->>'Stripe Amount','0') not in ('','0')
                       then '$' || (mp.at_fields->>'Stripe Amount') end),
         case lower(coalesce(digest.attr_clean(mp.at_fields->>'Stripe Subscription Status'), ''))
           when 'active' then 'Active - all good'
           when 'trialing' then 'In your trial period'
           when 'past_due' then 'A payment did not go through - your membership is still active. Update your card here: https://checkout.mds.co/p/login/8wM5l70XvaBC6Ji000 - or reply YES and I will connect you with the team.'
           when 'unpaid' then 'Payments are behind and need attention - update your payment method here: https://checkout.mds.co/p/login/8wM5l70XvaBC6Ji000 - or reply YES and I will open a ticket with the team.'
           when 'canceled' then 'Your subscription shows as canceled - if that is unexpected, reply YES and I will flag it to the team.'
           when 'incomplete' then 'Your payment setup did not finish - reply YES and I will connect you with the team.'
           when 'paused' then 'Your subscription is paused.'
           when '' then null
           else 'There is a billing state on your account worth checking - reply YES and I will connect you with the team.'
         end,
         coalesce(digest.attr_clean(mp.at_fields->>'Stripe Billing Cycle'), digest.attr_clean(mp.at_fields->>'Stripe Recurring Interval')),
         null::text,
         nullif(nullif(digest.attr_clean(mp.at_fields->>'Annual Payment'), '0'), ''),
         case when coalesce(nullif(digest.attr_clean(mp.at_fields->>'Member Paid Date - For Dashboard'), ''),
                             nullif(digest.attr_clean(mp.at_fields->>'WA Member Since Date'), '')) ~ '^\d{4}-\d{2}-\d{2}'
                   then to_char((left(coalesce(nullif(digest.attr_clean(mp.at_fields->>'Member Paid Date - For Dashboard'), ''),
                             nullif(digest.attr_clean(mp.at_fields->>'WA Member Since Date'), '')),10))::date, 'Mon DD, YYYY')
                   else coalesce(nullif(digest.attr_clean(mp.at_fields->>'Member Paid Date - For Dashboard'), ''),
                             nullif(digest.attr_clean(mp.at_fields->>'WA Member Since Date'), '')) end,
         digest.attr_clean(mp.at_fields->>'Year Joined'),
         case when (mp.at_fields->>'Next Renewal Payment Due Date') ~ '^\d{4}-\d{2}-\d{2}'
              then to_char((left(mp.at_fields->>'Next Renewal Payment Due Date',10))::date, 'Mon DD, YYYY')
              else digest.attr_clean(mp.at_fields->>'Next Renewal Payment Due Date') end,
         nullif(digest.attr_clean(mp.at_fields->>'Chapter Affiliation'), 'No Chapter Affiliation'),
         case when coalesce(mp.at_fields->>'Stripe Subscription ID','') <> ''
           and (mp.at_fields->>'Stripe Next Invoice Date') ~ '^\d{4}-\d{2}-\d{2}'
              then to_char((left(mp.at_fields->>'Stripe Next Invoice Date',10))::date, 'Mon DD, YYYY')
              when coalesce(mp.at_fields->>'Stripe Subscription ID','') = '' then null
              else digest.attr_clean(mp.at_fields->>'Stripe Next Invoice Date') end,
         case when coalesce(mp.at_fields->>'Stripe Subscription ID','') <> ''
           and coalesce(mp.at_fields->>'Stripe Next Invoice Amount','') <> ''
              then '$' || trim(to_char((mp.at_fields->>'Stripe Next Invoice Amount')::numeric, 'FM999,999,990.00')) end,
         digest.attr_clean(mp.at_fields->>'Payment Frequency'),
         case when coalesce(mp.at_fields->>'Membership Fee (Used)','') <> ''
              then '$' || trim(to_char((mp.at_fields->>'Membership Fee (Used)')::numeric, 'FM999,999,990.00')) end,
         case when (mp.at_fields->>'Wild Apricot Balance') ~ '^-?\d+(\.\d+)?$' then
           case when (mp.at_fields->>'Wild Apricot Balance')::numeric > 0
                then '$' || trim(to_char((mp.at_fields->>'Wild Apricot Balance')::numeric, 'FM999,999,990.00'))
                     || ' credit on your MDS account'
                when (mp.at_fields->>'Wild Apricot Balance')::numeric < 0
                then '$' || trim(to_char(abs((mp.at_fields->>'Wild Apricot Balance')::numeric), 'FM999,999,990.00'))
                     || ' currently owed on your MDS account'
                else 'no credit on your MDS account right now - balance is $0' end
         end,
         case when (mp.at_fields->>'Wild Apricot Balance') ~ '^-?\d+(\.\d+)?$'
              then 'INTERNAL, never quote: this credit is an MDS account balance, NOT Stripe. '
                   || 'The billing portal cannot show or apply it - NEVER attach the portal link '
                   || 'to a credit answer. The MDS team applies credit at renewal or on request.' end,
         'https://checkout.mds.co/p/login/8wM5l70XvaBC6Ji000'::text
  from digest.member_profiles mp
  left join digest.member_attributes ma on ma.at_member_id = mp.at_member_id
  where mp.at_member_id = v_atid;
end $function$
